using System;using System.IO;using System.Text;using SPICA.Formats.CtrGfx;using SPICA.Formats.CtrGfx.Animation;using SPICA.Formats.CtrGfx.Model;
class Program{
static int I(byte[] b,int p)=>BitConverter.ToInt32(b,p);static int Ptr(byte[] b,int p)=>p+I(b,p);
static int Main(string[] args){try{
var scene=Gfx.Open(args[0]);var h=scene.ToH3D();if(scene.SkeletalAnimations.Count>1||scene.MaterialAnimations.Count!=0||scene.Textures.Count!=3)throw new Exception("Resource mismatch");
int meshes=0,triangles=0;foreach(var m in scene.Models){if(m is not GfxModelSkeletal sk)throw new Exception("Missing rigid skeleton");foreach(var b in sk.Skeleton.Bones)if(b.Name.StartsWith("Forge")){if((int)b.BillboardMode!=5||b.Translation.Length()!=0||b.Rotation.Length()!=0)throw new Exception("Facing/rest mismatch");}}
foreach(var m in h.Models)foreach(var mesh in m.Meshes){meshes++;var v=mesh.GetVertices();foreach(var sub in mesh.SubMeshes){if(sub.BoneIndicesCount!=1)throw new Exception("Non rigid");foreach(var i in sub.Indices)if(i>=v.Length)throw new Exception("Bad index");triangles+=sub.Indices.Length/3;}}
if(meshes!=6||triangles!=244)throw new Exception("Wrong geometry");
int faces=0,papers=0;float backdropScale=args.Length>2?float.Parse(args[2],System.Globalization.CultureInfo.InvariantCulture):1f;
foreach(var model in h.Models)foreach(var mesh in model.Meshes){var material=model.Materials[mesh.MaterialIndex].Name;if(material=="Face"){faces++;foreach(var v in mesh.GetVertices())if(Math.Abs(v.Position.Z-1.185f)>.0001f||Math.Abs(v.Normal.X)>.0001f||Math.Abs(v.Normal.Y)>.0001f||Math.Abs(v.Normal.Z-1)>.0001f)throw new Exception("Coin face is tilted");}if(material=="Paper"){papers++;float minX=float.MaxValue,maxX=float.MinValue,minY=float.MaxValue,maxY=float.MinValue;foreach(var v in mesh.GetVertices()){minX=Math.Min(minX,v.Position.X);maxX=Math.Max(maxX,v.Position.X);minY=Math.Min(minY,v.Position.Y);maxY=Math.Max(maxY,v.Position.Y);}if(Math.Abs(maxX-minX-33.6f*backdropScale)>.001f||Math.Abs(maxY-minY-16.8f*backdropScale)>.001f||Math.Abs(minX+maxX)>.001f||Math.Abs(minY+maxY-2)>.001f)throw new Exception("Backdrop size/center mismatch");}}
if(faces!=1||papers!=1)throw new Exception("Missing face/backdrop");
if(scene.SkeletalAnimations.Count==0){Console.WriteLine("PASS complete CGFX: six rigid meshes, 244 triangles, identity facing bones; front face points straight forward; zero skeletal or material animations");return 0;}
byte[] reference=File.ReadAllBytes(args[1]);int a=Encoding.ASCII.GetString(reference).IndexOf("CANM");int member=Ptr(reference,Ptr(reference,a+28)+40);
byte[] candidate=File.ReadAllBytes(args[0]);int ca=Encoding.ASCII.GetString(candidate).IndexOf("CANM"),cm=Ptr(candidate,Ptr(candidate,ca+28)+40);if((I(candidate,cm)&~0x400000)!=I(reference,member))throw new Exception("Channel flags differ from Starfox");for(int off=20;off<48;off++)if(candidate[cm+off]!=reference[member+off])throw new Exception("Scale/rotation payload differs from Starfox");
foreach(var anim in scene.SkeletalAnimations){if(anim.FramesCount!=240||anim.Elements.Count!=1)throw new Exception("Wrong animation");foreach(var e in anim.Elements){if(e.Name!="ForgeMedallion"||e.Content is not GfxAnimTransform t)throw new Exception("Wrong target");if(t.ScaleExists||t.RotationExists||!t.TranslationExists)throw new Exception("Expected translation-only sparse animation");var xyz=new[]{t.TranslationX,t.TranslationY,t.TranslationZ};for(int axis=0;axis<3;axis++){int curve=Ptr(reference,member+48+axis*4),segment=Ptr(reference,curve+20);if(xyz[axis].KeyFrames.Count!=121)throw new Exception("Lost keys");for(int i=0;i<121;i++){float frame=BitConverter.ToSingle(reference,segment+20+i*8),value=BitConverter.ToSingle(reference,segment+24+i*8);var k=xyz[axis].KeyFrames[i];if(k.Frame!=frame||k.Value!=value)throw new Exception("Translation differs from packaged Starfox");}}}}
Console.WriteLine("PASS complete CGFX: six rigid meshes, 244 triangles, front-facing coin, verified backdrop dimensions; all 363 translation keys exactly equal Starfox; scale/rotation channels absent as in Starfox; zero material animation");return 0;
}catch(Exception e){Console.WriteLine(e);return 1;}}}
